      ro: ["Comemorează tragedia din 7 martie 2021.", "Loc de comemorare și reflecție națională.", "Design modern cu o semnificație simbolică profundă.", "Loc important pentru ceremoniile de comemorare ale orașului."],
      en: ["Commemorates the tragedy of March 7, 2021.", "Place of national remembrance and reflection.", "Modern design with high symbolic meaning.", "Important site for city memorial services."],
      es: ["Recuerda la tragedia del 7 de marzo de 2021.", "Lugar de conmemoración nacional y reflexión.", "Diseño moderno con alto significado simbólico.", "Lugar importante para las ceremonias de recuerdo de los ciudadanos."],
      pt: ["Recorda a tragédia de 7 de março de 2021.", "Local de memória nacional e reflexão.", "Design moderno com elevado significado simbólico.", "Local importante para cerimónias fúnebres dos habitantes da cidade."],
